void validateShakerGroups(const MultiheadsGeometryResult &result){
    const auto &owners=result.placements;std::vector<size_t> indexes(owners.size());
    for(size_t n=0;n<indexes.size();++n)indexes[n]=indexes.size()-1-n;
    const auto constraints=multiheadsShakerConstraints(owners,indexes);
    size_t expected=0;for(const auto &owner:owners)if(owner->group58&&owner->group58->members.front().lock()==owner)expected+=2*(owner->group58->members.size()-1);
    require(constraints.size()==expected,PN2S_INTERNAL,"Multiheads Shaker did not emit both native equality types per sister");
    std::vector<ShakerPart> parts(owners.size());LinearModel model;
    for(size_t n=0;n<owners.size();++n){const auto &owner=owners[n];auto &part=parts[indexes[n]];
        part.position={double(owner->x48)/1e6,double(owner->y50)/1000.};part.reference50=part.position;
        for(size_t axis=0;axis<2;++axis)part.columns[axis]=model.addColumn(-1000,1000,double(int32_t((n*7+axis*3)%5)-2));}
    for(const auto &constraint:constraints){require(constraint.type==0||constraint.type==4,PN2S_INTERNAL,"Multiheads invented a non-native sister constraint");
        require(shakerPairConstraintRows(constraint,false,parts,model)==2,PN2S_INTERNAL,"Sister equality lost a hard bound");}
    const auto solution=solveShakerHighs(model,10);require(solution.status==0,PN2S_INTERNAL,"Multiheads hard-link LP failed");
    for(const auto &constraint:constraints){const auto axis=size_t(shakerPairConstraintAxis(constraint.type));const auto &a=parts[constraint.first],&b=parts[constraint.second];
        const auto delta=solution.primal[a.columns[axis]]-solution.primal[b.columns[axis]];
        require(std::abs(delta-(a.reference50[axis]-b.reference50[axis]))<1e-7,PN2S_INTERNAL,"Shaker independently moved linked cutting heads");}
    for(size_t n=0;n<owners.size();++n)if(owners[n]->group58&&owners[n]->group58->members.size()>1){auto partial=owners;partial.erase(partial.begin()+n);bool rejected=false;
        try{multiheadsShakerConstraints(partial);}catch(const Failure &error){rejected=error.code==PN2S_INVALID;}
        require(rejected,PN2S_INTERNAL,"Partial warm sister group was silently accepted");break;}
}
